\title{Optimality of the Density Threshold for\\ Linear $r$-Uniform Hypergraphs}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\maketitle

\begin{abstract}
A hypergraph is \emph{linear} (equivalently, a \emph{partial Steiner system}) when
any two distinct edges meet in at most one vertex. We establish, with full rigor, the
sharp pair-counting density threshold for finite linear $r$-uniform hypergraphs: on
$n$ vertices, the number of edges $m$ satisfies $m \binom{r}{2} \le \binom{n}{2}$,
equivalently $m \le n(n-1)/(r(r-1))$ over the reals. We prove that this threshold is
\emph{optimal}: a Steiner system $S(2,r,n)$ --- a linear $r$-uniform family covering
every pair of vertices --- attains equality $m \binom{r}{2} = \binom{n}{2}$, so the
leading coefficient $1/(r(r-1))$ cannot be improved. The proof rests on a single
structural observation: linearity is equivalent to the pairwise disjointness of the
families of $2$-element subsets (``pair sets'') of the edges, after which the bound is
a transparent double count of vertex pairs and the Steiner case is the same identity
with containment upgraded to equality. All statements have been formalized and
machine-verified. We situate the result as the $e=2$ boundary case of the
Brown--Erd\H{o}s--S\'os extremal function and as the anchor of the Keevash--Long
sparse linear regime, and we provide algorithms, numerical demonstrations, and a
program of conjectures for sharpening the threshold.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Extremal hypergraph theory asks how dense a combinatorial structure can be while
avoiding a prescribed sub-configuration. Among the most natural structural
restrictions is \emph{linearity}: the requirement that any two distinct edges share
at most one vertex. Linear hypergraphs --- also called \emph{partial Steiner systems}
--- model lines in incidence geometry, blocks in balanced experimental designs,
codewords in constant-weight codes, and key-distribution patterns in cryptography. In
each setting one asks: how many edges can a linear $r$-uniform hypergraph on $n$
vertices contain, and which hypergraphs are extremal?

This paper gives a complete answer for the basic density question. The upper bound is
classical folklore (a one-line double count), but our contribution is the precise,
self-contained, and machine-verified packaging of both the bound and its optimality,
including the exact characterization of equality via Steiner systems. The result is
the cornerstone $e=2$ case of the Brown--Erd\H{o}s--S\'os (BES) programme and the
density anchor for the Keevash--Long (2023) study of sparse linear hypergraphs.

\subsection{Summary of results}
Let $V$ be a finite vertex set with $n=|V|$, and let a hypergraph be a finite family
$\E$ of edges, each edge a subset of $V$. We prove:
\begin{enumerate}
  \item (Density threshold; \texttt{linear\_card\_le}) If $\E$ is $r$-uniform and
  linear, then $|\E|\binom{r}{2} \le \binom{n}{2}$.
  \item (Optimality; \texttt{steiner\_card\_eq}) If $\E$ is a Steiner system
  $S(2,r,n)$, then $|\E|\binom{r}{2} = \binom{n}{2}$.
  \item (Real-valued form; \texttt{linear\_density\_real}) For $r \ge 2$, a linear
  $r$-uniform $\E$ satisfies $|\E| \le n(n-1)/(r(r-1))$ over $\mathbb{R}$.
\end{enumerate}
The structural engine is:
\begin{enumerate}\setcounter{enumi}{3}
  \item (Disjointness; \texttt{pairs\_disjoint}) Linearity is equivalent to the
  pairwise disjointness of the pair sets $\binom{e}{2}$ over edges $e \in \E$.
  \item (Containment; \texttt{biUnion\_pairs\_subset}) The union of the pair sets is
  contained in the set of all $2$-subsets of $V$.
\end{enumerate}

\section{Definitions}
Throughout, $V$ is a finite vertex set with $n=|V|$, and $\E$ is a finite family of
finite subsets of $V$ (the \emph{edges}). For a finite set $e$ and $k \in \mathbb{N}$,
write $\binom{e}{k}$ for the family of $k$-element subsets of $e$, so that
$\bigl|\binom{e}{k}\bigr| = \binom{|e|}{k}$.

\begin{definition}[Uniformity]
$\E$ is \textbf{$r$-uniform} if every edge has exactly $r$ vertices:
$\forall e \in \E,\ |e| = r.$
\end{definition}

\begin{definition}[Linearity]
$\E$ is \textbf{linear} if any two distinct edges meet in at most one vertex:
$\forall e_1, e_2 \in \E,\ e_1 \ne e_2 \Rightarrow |e_1 \cap e_2| \le 1.$
A linear $r$-uniform hypergraph is also called a \emph{partial Steiner system}.
\end{definition}

\begin{definition}[Steiner system]
$\E$ is a \textbf{Steiner system} $S(2,r,n)$ if it is $r$-uniform, linear, and
\textbf{covers every pair}: every $2$-element subset $p \subseteq V$ is contained in
some edge, $\forall p \in \binom{V}{2},\ \exists e \in \E,\ p \subseteq e.$ Linearity
forces each pair to be covered at most once, so a Steiner system covers every pair
exactly once.
\end{definition}

We use the elementary identities $\binom{r}{2} = r(r-1)/2$ and
$\binom{n}{2} = n(n-1)/2$.

\section{The structural lemma: linearity as pairwise disjointness}

\begin{lemma}[Pair sets are disjoint; \texttt{pairs\_disjoint}]
\label{lem:disjoint}
If $\E$ is linear, then the map $e \mapsto \binom{e}{2}$ sends $\E$ to a family of
pairwise disjoint sets: for distinct $e,f \in \E$,
$\binom{e}{2} \cap \binom{f}{2} = \varnothing.$
\end{lemma}

\begin{proof}
Suppose toward a contradiction that some pair $p$ lies in both $\binom{e}{2}$ and
$\binom{f}{2}$ for distinct edges $e \ne f$. Then $p \subseteq e$ and $p \subseteq f$,
so $p \subseteq e \cap f$; since $|p|=2$, monotonicity of cardinality gives
$|e \cap f| \ge 2$, contradicting linearity ($|e\cap f| \le 1$). Hence no common pair
exists.
\end{proof}

The converse holds equally easily, so linearity and pairwise pair-disjointness are
equivalent; we use only the stated direction.

\begin{lemma}[Pair sets live among all pairs; \texttt{biUnion\_pairs\_subset}]
\label{lem:subset}
For any family $\E$, $\displaystyle\bigcup_{e \in \E} \binom{e}{2} \subseteq \binom{V}{2}.$
\end{lemma}

\begin{proof}
Each member of the union is a $2$-element subset of some edge $e \subseteq V$, hence a
$2$-element subset of $V$.
\end{proof}

\section{The density threshold}

\begin{theorem}[Density threshold; \texttt{linear\_card\_le}]
\label{thm:bound}
Let $\E$ be an $r$-uniform linear hypergraph on $n=|V|$ vertices with $m=|\E|$ edges.
Then $m\binom{r}{2} \le \binom{n}{2}.$
\end{theorem}

\begin{proof}
We count $\bigcup_e \binom{e}{2}$ two ways. Since $\E$ is $r$-uniform, each edge $e$
contributes $\bigl|\binom{e}{2}\bigr| = \binom{r}{2}$ pairs, so
$\sum_{e \in \E}\bigl|\binom{e}{2}\bigr| = m\binom{r}{2}$. By Lemma~\ref{lem:disjoint}
the families $\binom{e}{2}$ are pairwise disjoint, so additivity of size over a
disjoint union gives
$\bigl|\bigcup_e \binom{e}{2}\bigr| = \sum_e \bigl|\binom{e}{2}\bigr| = m\binom{r}{2}$.
By Lemma~\ref{lem:subset} the union lies inside $\binom{V}{2}$, so by monotonicity of
cardinality $m\binom{r}{2} = \bigl|\bigcup_e\binom{e}{2}\bigr| \le \bigl|\binom{V}{2}\bigr| = \binom{n}{2}$.
\end{proof}

The bound holds for every uniform linear family, including the empty hypergraph, where
it reads $0 \le \binom{n}{2}$.

\begin{corollary}[Real density bound; \texttt{linear\_density\_real}]
For $r \ge 2$, a linear $r$-uniform hypergraph satisfies
$m \le \dfrac{n(n-1)}{r(r-1)}$ over $\mathbb{R}$.
\end{corollary}

\begin{proof}
Multiply Theorem~\ref{thm:bound} by $2$ and use $2\binom{k}{2}=k(k-1)$ to obtain the
integer inequality $m\,r(r-1) \le n(n-1)$. Since $r\ge 2$ gives $r(r-1)>0$, divide to
obtain the stated bound.
\end{proof}

The leading coefficient in $n^2$ is exactly $1/(r(r-1))$.

\section{Optimality: Steiner systems attain the threshold}

\begin{theorem}[Optimality; \texttt{steiner\_card\_eq}]
\label{thm:opt}
Let $\E$ be a Steiner system $S(2,r,n)$. Then $m\binom{r}{2} = \binom{n}{2}.$
\end{theorem}

\begin{proof}
We rerun the double count of Theorem~\ref{thm:bound} but upgrade the containment of
Lemma~\ref{lem:subset} to an equality. By the covering axiom every pair
$p \in \binom{V}{2}$ lies in some edge $e$, hence $p \in \binom{e}{2} \subseteq
\bigcup_e \binom{e}{2}$; with the reverse inclusion of Lemma~\ref{lem:subset} this
yields $\bigcup_e \binom{e}{2} = \binom{V}{2}$. Linearity and
Lemma~\ref{lem:disjoint} give pairwise disjointness, so
$\bigl|\bigcup_e \binom{e}{2}\bigr| = \sum_e \binom{|e|}{2} = m\binom{r}{2}$.
Equating cardinalities gives $m\binom{r}{2} = \bigl|\binom{V}{2}\bigr| = \binom{n}{2}$.
\end{proof}

\paragraph{Optimality of the coefficient.}
The factor $\binom{r}{2}$ appears identically on the $\le$ side of
Theorem~\ref{thm:bound} and the $=$ side of Theorem~\ref{thm:opt}. Hence no
coefficient smaller than $1/(r(r-1))$ can serve as a valid upper bound for all $n$:
the Steiner systems saturate the bound. Whenever $S(2,r,n)$ exists, the threshold is
achieved exactly.

\paragraph{Existence of extremal witnesses.}
Steiner systems exist for infinitely many $n$ for each $r$. The classical necessary
divisibility conditions are $(r-1)\mid(n-1)$ and $r(r-1)\mid n(n-1)$, and for $r=3$
the admissible orders are $n \equiv 1,3 \pmod 6$, giving Steiner triple systems
$S(2,3,n)$ for arbitrarily large $n$. The smallest nontrivial case is the Fano plane
$S(2,3,7)$.

\section{Algorithms}

\subsection{Linearity / Steiner verification by pair-incidence counting}
Given an explicit family $\E$ on $V$, verify linearity, uniformity, and the Steiner
property in time $O(m\,r^2)$ via a multiplicity table over pairs. For each edge,
enumerate its $\binom{r}{2}$ pairs and increment a counter keyed by the sorted pair.
Then $\E$ is uniform iff every edge has size $r$; linear iff every counter is $\le 1$;
and Steiner iff additionally every counter is $\ge 1$ (hence exactly $1$), i.e. the
table covers all of $\binom{V}{2}$. The total count of touched pairs equals
$m\binom{r}{2}$ when linear, directly witnessing Theorems~\ref{thm:bound} and
\ref{thm:opt}.

\subsection{Threshold evaluation and admissibility}
The threshold $\lfloor \binom{n}{2}/\binom{r}{2}\rfloor$ is computed in $O(1)$
arithmetic; Steiner-admissibility is the $O(1)$ predicate $(r-1)\mid(n-1) \wedge
r(r-1)\mid n(n-1)$.

\subsection{Fano / projective-plane generator}
For $r-1=q$ a prime power, the projective plane $\mathrm{PG}(2,q)$ gives a Steiner
system $S(2,q+1,q^2+q+1)$: its $q^2+q+1$ lines, each containing $q+1$ points,
saturate the threshold by construction.

\section{Worked examples}
\begin{itemize}
  \item \textbf{Fano plane $S(2,3,7)$:} threshold $21/3=7$; the seven blocks
  $\{1,2,3\},\{1,4,5\},\{1,6,7\},\{2,4,6\},\{2,5,7\},\{3,4,7\},\{3,5,6\}$ cover each
  of the $21$ pairs once, so $7\cdot 3=21$, equality.
  \item \textbf{$S(2,3,9)$:} threshold $36/3=12$; $\mathrm{AG}(2,3)$ gives $12$ blocks,
  $12\cdot 3=36$, equality.
  \item \textbf{Non-admissible $n=8$, $r=3$:} $28/3 = 9.33\ldots$, so $m \le 9$; since
  $3\nmid 28$, no Steiner triple system exists, and $9\cdot 3 = 27 < 28$.
  \item \textbf{$S(2,4,16)$:} threshold $120/6=20$; $\mathrm{AG}(2,4)$ gives $20$
  blocks, $20\cdot 6=120$, equality.
\end{itemize}

\section{Applications}
\begin{itemize}
  \item \textbf{Design of experiments:} balanced incomplete block designs with
  $\lambda=1$ are exactly Steiner systems; Theorem~\ref{thm:opt} fixes the minimal
  number of blocks $b=\binom{n}{2}/\binom{r}{2}$.
  \item \textbf{Coding theory:} Steiner systems and projective planes yield optimal
  constant-weight codes; the density bound caps the codebook size.
  \item \textbf{Cryptographic key predistribution:} linear hypergraphs bound the
  number of keyed groups for a given storage budget.
  \item \textbf{Incidence geometry:} pair-counting is the elementary heart of
  point--line incidence bounds.
\end{itemize}

\section{Discussion}
The condition ``any two edges meet in $\le 1$ vertex'' is the $e=2$ instance of the
Brown--Erd\H{o}s--S\'os extremal function $f_r(n;v,e)$. Linearity forbids $2$ edges on
$\le 2r-2$ vertices, and Theorem~\ref{thm:bound} is the exact cap at that level with
coefficient pinned by Theorem~\ref{thm:opt}. The next boundary, $e=3$ (the
$(6,3)$-problem for $r=3$), exhibits the $n^{2-o(1)}$ behaviour of
Ruzsa--Szemer\'edi. The result is also the density anchor of the Keevash--Long (2023)
study of sparse linear hypergraphs, where $1/(r(r-1))$ is the normalizing constant.
The proof is purely combinatorial and coefficient-exact: upper bound and extremal
construction interlock through the identical factor $\binom{r}{2}$.

\section{Future directions}
\begin{conjecture}[Divisibility characterization of equality]
A Steiner system $S(2,r,n)$ requires $(r-1)\mid(n-1)$ and $r(r-1)\mid n(n-1)$; a
concrete step is to prove $\mathrm{IsSteiner}(\E,r) \Rightarrow (r-1)\mid(n-1)$ via
double counting edges through a fixed vertex.
\end{conjecture}
\begin{conjecture}[Strict bound off the Steiner locus]
If $r(r-1)\nmid n(n-1)$ then $m\binom{r}{2} \le \binom{n}{2}-1$ strictly.
\end{conjecture}
\begin{conjecture}[BES at $e=3$]
The maximum edge count under the $(3,3r-2)$-property is $o(n^2)$ but
$\Omega(n^{2-o(1)})$, the $(6,3)$-theorem analogue.
\end{conjecture}
\begin{conjecture}[Keevash--Long threshold function]
$t_r(n)/(n^2/(r(r-1))) \to 1$ along Steiner-admissible orders, with convergence
governed by the largest prime power $\le r-1$.
\end{conjecture}
\begin{conjecture}[Fractional relaxation]
With weights $w$ on $r$-sets satisfying $\sum_{e \ni \{x,y\}} w(e) \le 1$ for every
pair, the fractional optimum $\sum_e w(e)$ equals $\binom{n}{2}/\binom{r}{2}$ for all
$n \ge r$.
\end{conjecture}

\section{Conclusion}
We have given a complete, verified, self-contained account of the linear $r$-uniform
density threshold $m\binom{r}{2} \le \binom{n}{2}$, with Steiner systems achieving
equality and certifying that the coefficient $1/(r(r-1))$ is sharp. The argument
reduces transparently to a double count of vertex pairs, legitimized by the
equivalence between linearity and pairwise pair-disjointness.

