function PROJECTIVE_PLANE(q):            // q prime
    reps <- []                            // normalized point reps
    for v in GF(q)^3 \ {0}:
        nv <- normalize(v)                // scale so first nonzero entry = 1
        if nv not seen: add nv to reps
    index <- map each rep to its position
    lines <- []
    for a in reps:                        // a is a 'line' (dual vector)
        L <- { index[p] : p in reps, a . p = 0 (mod q) }
        append L to lines
    return lines, |reps|                  // S(2, q+1, q^2+q+1)
